 long reserved(String o){return db.queryForObject("SELECT reserved_qty FROM inventory_balances WHERE offer_id=?",Long.class,UUID.fromString(o));}

 @Autowired cn.pawday.payment.PaymentService payments;@Autowired cn.pawday.payment.SimulatedPaymentGateway gateway;@Autowired org.springframework.transaction.support.TransactionTemplate tx;
 Response payment(String u,String p){return read("/consumer/payments/"+p,u);}
 Response attempt(String u,String p,String channel,String k){return req("POST","/consumer/payments/"+p+"/attempts",Map.of("channel",channel,"client_platform","ANDROID"),u,Map.of("Idempotency-Key",k));}
 Response query(String u,String p){return req("POST","/consumer/payments/"+p+"/requery",null,u,Map.of());}
