 Fixture fixture(){String u=consumer(),o=ready();shipping();var order=order(u,q(u,o,List.of()),key());assertEquals(200,order.status(),order.body().toString());return new Fixture(u,o,order,pid(order));}
 void providerSuccess(String a,long amount,String currency){db.update("UPDATE simulated_payment_transactions SET status='SUCCEEDED',amount_fen=?,currency=?,transaction_id=coalesce(transaction_id,?) WHERE attempt_no=(SELECT attempt_no FROM payment_attempts WHERE id=?)",amount,currency,"SIM-"+a,UUID.fromString(a));}
 @Test void serverConfirmationConsumesExactlyOnce(){var f=fixture();String k=key();var created=attempt(f.u(),f.payment(),"WECHAT",k);assertEquals(200,created.status(),created.body().toString());assertEquals("PROCESSING",created.data().get("status").asString());String a=aid(created);assertEquals(a,aid(attempt(f.u(),f.payment(),"WECHAT",k)));var success=outcome(f.u(),f.payment(),a,"SUCCEEDED");assertEquals(200,success.status(),success.body().toString());assertEquals("SUCCEEDED",success.data().get("status").asString());assertEquals("WECHAT",success.data().get("final_channel").asString());assertEquals(a,success.data().get("successful_attempt_id").asString());assertEquals(18,balance(f.offer()));assertEquals(0,reserved(f.offer()));assertEquals("FULFILLING",read("/consumer/orders/"+f.order().id(),f.u()).data().get("status").asString());assertEquals("CONSUMED",db.queryForObject("SELECT status FROM inventory_reservations WHERE order_id=?",String.class,UUID.fromString(f.order().id())));for(int i=0;i<3;i++)assertEquals("SUCCEEDED",query(f.u(),f.payment()).data().get("status").asString());assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_sale_events WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_receipts WHERE attempt_id=?",Integer.class,UUID.fromString(a)));assertEquals(1,db.queryForObject("SELECT count(*) FROM outbox_event WHERE event_type='OrderPaid' AND aggregate_id=?",Integer.class,f.order().id()));assertEquals(409,attempt(f.u(),f.payment(),"ALIPAY",key()).status());assertEquals(409,cancel(f.u(),f.order().id(),1,key()).status());}
 @Test void successfulPaymentRedeemsReservedCoupon(){String u=consumer(),o=ready();shipping();String c=coupon(u,"PLATFORM",200,0);var ord=order(u,q(u,o,List.of(c)),key());String p=pid(ord),a=aid(attempt(u,p,"ALIPAY",key()));assertEquals(200,outcome(u,p,a,"SUCCEEDED").status());assertEquals("USED",db.queryForObject("SELECT status FROM user_coupons WHERE id=?",String.class,UUID.fromString(c)));assertEquals(1,db.queryForObject("SELECT count(*) FROM coupon_redemption_events WHERE coupon_id=?",Integer.class,UUID.fromString(c)));query(u,p);assertEquals(1,db.queryForObject("SELECT count(*) FROM coupon_redemption_events WHERE coupon_id=?",Integer.class,UUID.fromString(c)));}
 @Test void pendingCannotReleaseAndSafeCloseAllowsCancellation(){var f=fixture();attempt(f.u(),f.payment(),"WECHAT",key());assertEquals(409,cancel(f.u(),f.order().id(),0,key()).status());assertEquals(2,reserved(f.offer()));assertEquals("PENDING",closeAttempt(f.u(),f.payment()).data().get("status").asString());assertEquals(200,cancel(f.u(),f.order().id(),0,key()).status());assertEquals(0,reserved(f.offer()));assertEquals(20,balance(f.offer()));assertEquals("CLOSED",payment(f.u(),f.payment()).data().get("status").asString());}
 @Test void channelSwitchClosesOldBeforeOpeningNew(){var f=fixture();var first=attempt(f.u(),f.payment(),"WECHAT",key());String old=aid(first);var second=attempt(f.u(),f.payment(),"ALIPAY",key());assertEquals(200,second.status(),second.body().toString());assertNotEquals(old,aid(second));assertEquals("CANCELLED",second.data().get("attempts").get(0).get("status").asString());assertEquals(1,db.queryForObject("SELECT count(*) FROM simulated_payment_transactions WHERE status='PENDING' AND attempt_no IN (SELECT attempt_no FROM payment_attempts WHERE payment_id=?)",Integer.class,UUID.fromString(f.payment())));}
 @Test void uncertainResultBlocksSwitchAndExpirationUntilConfirmed(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));assertEquals("UNKNOWN",outcome(f.u(),f.payment(),a,"UNKNOWN").data().get("attempts").get(0).get("status").asString());assertEquals(409,attempt(f.u(),f.payment(),"ALIPAY",key()).status());assertEquals(409,closeAttempt(f.u(),f.payment()).status());OFFSET.set(901);payments.refresh(UUID.fromString(a),true);orders.expireBatch();assertEquals(2,reserved(f.offer()));assertEquals("PROCESSING",db.queryForObject("SELECT status FROM payments WHERE id=?",String.class,UUID.fromString(f.payment())));OFFSET.set(0);assertEquals("PENDING",outcome(f.u(),f.payment(),a,"FAILED").data().get("status").asString());OFFSET.set(901);orders.expireBatch();assertEquals(0,reserved(f.offer()));}
 @Test void failureKeepsReservationAndAllowsRetry(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));assertEquals("PENDING",outcome(f.u(),f.payment(),a,"FAILED").data().get("status").asString());assertEquals(2,reserved(f.offer()));assertEquals(200,attempt(f.u(),f.payment(),"ALIPAY",key()).status());}
 @Test void ownershipRealmAndAmountOverrideAreRejected(){var f=fixture();assertEquals(404,payment(consumer(),f.payment()).status());assertEquals(403,payment(merchant,f.payment()).status());assertEquals(403,read("/admin/payments/"+f.payment(),reader).status());assertEquals(200,read("/admin/payments/"+f.payment(),admin).status());assertEquals(400,req("POST","/consumer/payments/"+f.payment()+"/attempts",Map.of("channel","WECHAT","client_platform","ANDROID","amount_fen",1),f.u(),Map.of("Idempotency-Key",key())).status());assertEquals(400,attempt(f.u(),f.payment(),"OTHER",key()).status());assertEquals(400,attempt(f.u(),f.payment(),"WECHAT","short").status());assertEquals(0,db.queryForObject("SELECT count(*) FROM payment_attempts WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}
 @Test void sameKeyConcurrentRequestsDoNotCloseTheirOwnAttempt()throws Exception{var f=fixture();String k=key();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->attempt(f.u(),f.payment(),"WECHAT",k));var b=pool.submit(()->attempt(f.u(),f.payment(),"WECHAT",k));var first=a.get(30,TimeUnit.SECONDS);var second=b.get(30,TimeUnit.SECONDS);assertEquals(200,first.status());assertEquals(200,second.status());assertEquals(aid(first),aid(second));assertEquals("CHANNEL_PENDING",payment(f.u(),f.payment()).data().get("attempts").get(0).get("status").asString());assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_attempts WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}finally{pool.shutdownNow();}}
 @Test void differentPayloadSameKeyDoesNotCloseActiveAttempt(){var f=fixture();String k=key();attempt(f.u(),f.payment(),"WECHAT",k);assertEquals(409,attempt(f.u(),f.payment(),"ALIPAY",k).status());assertEquals("CHANNEL_PENDING",payment(f.u(),f.payment()).data().get("attempts").get(0).get("status").asString());}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"CNY","USD"}) void amountAndCurrencyMismatchCreateOriginalRouteCompensation(String currency){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));providerSuccess(a,currency.equals("CNY")?2501:2500,currency);var result=query(f.u(),f.payment());assertEquals(200,result.status(),result.body().toString());assertEquals("PENDING",result.data().get("status").asString());assertEquals(currency.equals("CNY")?"AMOUNT_MISMATCH":"CURRENCY_MISMATCH",result.data().get("cases").get(0).get("reason_code").asString());assertEquals("REFUNDED",result.data().get("cases").get(0).get("status").asString());assertEquals(20,balance(f.offer()));assertEquals(2,reserved(f.offer()));assertEquals(1,db.queryForObject("SELECT count(*) FROM simulated_payment_refunds WHERE transaction_id IN (SELECT channel_transaction_id FROM payment_receipts WHERE attempt_id=?)",Integer.class,UUID.fromString(a)));}
 @Test void lateCollectionNeverRevivesClosedOrder(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));closeAttempt(f.u(),f.payment());cancel(f.u(),f.order().id(),0,key());providerSuccess(a,2500,"CNY");var result=query(f.u(),f.payment());assertEquals("CLOSED",result.data().get("status").asString());assertEquals("LATE_COLLECTION",result.data().get("cases").get(0).get("reason_code").asString());assertEquals("REFUNDED",result.data().get("cases").get(0).get("status").asString());assertEquals(20,balance(f.offer()));assertEquals(0,reserved(f.offer()));assertEquals("CANCELLED",read("/consumer/orders/"+f.order().id(),f.u()).data().get("status").asString());query(f.u(),f.payment());assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_cases WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}
 @Test void duplicateCollectionDoesNotOverwriteWinningAttempt(){var f=fixture();String old=aid(attempt(f.u(),f.payment(),"WECHAT",key()));String winner=aid(attempt(f.u(),f.payment(),"ALIPAY",key()));outcome(f.u(),f.payment(),winner,"SUCCEEDED");providerSuccess(old,2500,"CNY");var result=query(f.u(),f.payment());assertEquals(winner,result.data().get("successful_attempt_id").asString());assertEquals("ALIPAY",result.data().get("final_channel").asString());assertEquals("DUPLICATE_COLLECTION",result.data().get("cases").get(0).get("reason_code").asString());assertEquals(18,balance(f.offer()));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_sale_events WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}
 @Test void durableProviderSuccessRecoversAfterOutboxFailure(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));providerSuccess(a,2500,"CNY");db.execute("CREATE FUNCTION reject_m43_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='OrderPaid' AND NEW.aggregate_id='"+f.order().id()+"' THEN RAISE EXCEPTION 'TEST ONLY';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER m43_fault BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION reject_m43_outbox()");try{assertEquals(503,query(f.u(),f.payment()).status());assertEquals(20,balance(f.offer()));assertEquals(2,reserved(f.offer()));assertEquals("PROCESSING",payment(f.u(),f.payment()).data().get("status").asString());}finally{db.execute("DROP TRIGGER m43_fault ON outbox_event");db.execute("DROP FUNCTION reject_m43_outbox()");}db.update("UPDATE payment_requery_schedule SET next_query_at=clock_timestamp() WHERE attempt_id=?",UUID.fromString(a));assertTrue(payments.recoverBatch()>0);assertEquals("SUCCEEDED",payment(f.u(),f.payment()).data().get("status").asString());assertEquals(18,balance(f.offer()));}
 @Test void providerIOCannotRunInsideBusinessTransaction(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));var request=new cn.pawday.payment.PaymentGateway.Request(UUID.fromString(a),"TEST ONLY","WECHAT",2500,"CNY");assertThrows(IllegalStateException.class,()->tx.execute(s->gateway.query(request)));}
 @Test void adminRequeryRequiresReverifyAndAudit(){var f=fixture();assertEquals(403,req("POST","/admin/payments/"+f.payment()+"/requery",null,reader,Map.of("Idempotency-Key",key())).status());assertEquals(403,req("POST","/admin/payments/"+f.payment()+"/requery",null,admin,Map.of("Idempotency-Key",key())).status());UUID grant=UUID.randomUUID();String proof=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?, ?,'payment.requery',?,?)",crypto.hash(proof),adminSession,Timestamp.from(clock.instant().plusSeconds(300)),Timestamp.from(clock.instant()));String k=key();var result=req("POST","/admin/payments/"+f.payment()+"/requery",null,admin,Map.of("Idempotency-Key",k,"X-Reverify-Token",proof));assertEquals(200,result.status(),result.body().toString());assertEquals(1,db.queryForObject("SELECT count(*) FROM audit_event WHERE action='payment.requery' AND object_id=?",Integer.class,f.payment()));assertEquals(200,req("POST","/admin/payments/"+f.payment()+"/requery",null,admin,Map.of("Idempotency-Key",k,"X-Reverify-Token",proof)).status());}

 @Test void pendingAttemptIsScheduledPromptlyAndPaidExpiryCannotRelease(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));assertTrue(db.queryForObject("SELECT next_query_at<clock_timestamp()+interval '10 seconds' FROM payment_requery_schedule WHERE attempt_id=?",Boolean.class,UUID.fromString(a)));outcome(f.u(),f.payment(),a,"SUCCEEDED");OFFSET.set(1000);orders.expireBatch();assertEquals(18,balance(f.offer()));assertEquals(0,reserved(f.offer()));assertEquals("FULFILLING",db.queryForObject("SELECT status FROM orders WHERE id=?",String.class,UUID.fromString(f.order().id())));}
 @Test void concurrentQueriesConfirmOneSale(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));providerSuccess(a,2500,"CNY");var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var x=pool.submit(()->query(f.u(),f.payment()));var y=pool.submit(()->query(f.u(),f.payment()));assertEquals(200,x.get().status());assertEquals(200,y.get().status());assertEquals(18,balance(f.offer()));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_sale_events WHERE payment_id=?",Integer.class,UUID.fromString(f.payment())));}catch(Exception e){throw new AssertionError(e);}finally{pool.shutdownNow();}}
 @Test void compensationCommitCrashReusesOriginalRefund(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));closeAttempt(f.u(),f.payment());cancel(f.u(),f.order().id(),0,key());providerSuccess(a,2500,"CNY");db.execute("CREATE FUNCTION reject_m43_refund() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='PaymentCompensated' AND NEW.aggregate_id='"+f.payment()+"' THEN RAISE EXCEPTION 'TEST ONLY';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER m43_refund_fault BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION reject_m43_refund()");try{assertEquals(503,query(f.u(),f.payment()).status());assertEquals("REFUND_PENDING",payment(f.u(),f.payment()).data().get("cases").get(0).get("status").asString());}finally{db.execute("DROP TRIGGER m43_refund_fault ON outbox_event");db.execute("DROP FUNCTION reject_m43_refund()");}assertEquals("REFUNDED",query(f.u(),f.payment()).data().get("cases").get(0).get("status").asString());assertEquals(1,db.queryForObject("SELECT count(*) FROM simulated_payment_refunds WHERE transaction_id IN (SELECT channel_transaction_id FROM payment_receipts WHERE attempt_id=?)",Integer.class,UUID.fromString(a)));}

 @Test void compensationRetriesStopAtEightAndAdminReverifyRestarts(){var f=fixture();String a=aid(attempt(f.u(),f.payment(),"WECHAT",key()));closeAttempt(f.u(),f.payment());cancel(f.u(),f.order().id(),0,key());providerSuccess(a,2500,"CNY");db.execute("CREATE FUNCTION reject_m43_provider_refund() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'TEST ONLY provider outage';END $$");db.execute("CREATE TRIGGER m43_provider_refund_fault BEFORE INSERT ON simulated_payment_refunds FOR EACH ROW EXECUTE FUNCTION reject_m43_provider_refund()");try{for(int i=0;i<8;i++){db.update("UPDATE payment_cases SET next_retry_at=clock_timestamp() WHERE payment_id=?",UUID.fromString(f.payment()));assertEquals(200,query(f.u(),f.payment()).status());}assertEquals("NEEDS_REVIEW",payment(f.u(),f.payment()).data().get("cases").get(0).get("status").asString());assertEquals(8,payment(f.u(),f.payment()).data().get("cases").get(0).get("attempt_count").asInt());query(f.u(),f.payment());assertEquals(8,payment(f.u(),f.payment()).data().get("cases").get(0).get("attempt_count").asInt());}finally{db.execute("DROP TRIGGER m43_provider_refund_fault ON simulated_payment_refunds");db.execute("DROP FUNCTION reject_m43_provider_refund()");}String proof=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'payment.requery',?,?)",crypto.hash(proof),adminSession,Timestamp.from(clock.instant().plusSeconds(300)),Timestamp.from(clock.instant()));var result=req("POST","/admin/payments/"+f.payment()+"/requery",null,admin,Map.of("Idempotency-Key",key(),"X-Reverify-Token",proof));assertEquals(200,result.status(),result.body().toString());assertEquals("REFUNDED",result.data().get("cases").get(0).get("status").asString());}

 @Test void missingReservedCouponRollsBackConfirmationAndCanRecover(){String o=ready(),u=consumer();shipping();String a=addressFor(u),i=addFor(u,o),c=coupon(u,"PLATFORM",100,1000);var q=quoteFor(u,i,a,List.of(c),false,key());var order=order(u,q.data().get("quote_id").asString(),key());String p=order.data().get("payment").get("id").asString(),attempt=aid(attempt(u,p,"WECHAT",key()));providerSuccess(attempt,2400,"CNY");db.update("UPDATE user_coupons SET status='AVAILABLE',reserved_order_id=NULL,reserved_from_status=NULL,reservation_expires_at=NULL,version=version+1 WHERE id=?",UUID.fromString(c));assertEquals(409,query(u,p).status());assertEquals(20,balance(o));assertEquals(2,reserved(o));assertEquals(0,db.queryForObject("SELECT count(*) FROM payment_receipts WHERE attempt_id=?",Integer.class,UUID.fromString(attempt)));db.update("UPDATE user_coupons SET status='RESERVED',reserved_order_id=?,reserved_from_status='AVAILABLE',version=version+1,reservation_expires_at=(SELECT expires_at FROM payments WHERE id=?) WHERE id=?",UUID.fromString(order.id()),UUID.fromString(p),UUID.fromString(c));assertEquals("SUCCEEDED",query(u,p).data().get("status").asString());assertEquals(18,balance(o));}
